def match_parens(lst):
    def is_good(s):
        count = 0
        for c in s:
            if c == '(':
                count += 1
            else:
                count -= 1
            if count < 0:
                return False
        return count == 0

    if is_good(lst[0] + lst[1]) or is_good(lst[1] + lst[0]):
        return 'Yes'
    return 'No'
```

